insert into public.facilities (id,name,description,category,address,lat,lng,author,status) select id,name,description,category,address,lat,lng,author,status from jsonb_to_recordset(expected) as e(id text,name text,description text,category text,address text,lat double precision,lng double precision,author text,status text) on conflict(id) do nothing;
if (select count(*) from public.facilities t join jsonb_to_recordset(expected) as e(id text,name text,description text,category text,address text,lat double precision,lng double precision,author text,status text) on t.id=e.id where t.owner_id is null and t.name is not distinct from e.name and t.description is not distinct from e.description and t.lat is not distinct from e.lat and t.lng is not distinct from e.lng and t.status is not distinct from e.status and t.address is not distinct from e.address and t.category is not distinct from e.category) <> jsonb_array_length(expected) then raise exception 'Conflicting facilities IDs or mismatched import'; end if;
end $import$;
